System.register([],function(e,t){var i;return{setters:[],execute:function(){e("t",[{id:"charyn",title:"Шарын шатқалы",grade:8,topic:"Жер бедері",level:2,source:"НЗМ, 2020 · 1-тапсырма",stimuli:[{kind:"text",title:"Шарын шатқалы",body:"Шарын ұзындығы 154 километр болатын, ал тік жартастарының биіктігі 300 метрге дейін жететін шөгінді жыныстардан тұратын кешен болып табылады. Оның тарихы 12 миллион жылды құрайды. Шөгінді жыныстардың қабаттарында тасқа айналған теңіз жануарларының қалдықтары көптеп кездеседі. Аңғар түбімен осыдан бірнеше миллион жыл бұрын Іле көлін қоректендірген Шарын өзені ағып жатыр.\n\nЖазда ауа температурасы 35°-қа дейін көтеріліп, қыста −6°-қа дейін төмендейді. Сол себептен туристерге көктемнің соңы мен жаздың басында немесе күз мезгілінде келу ұсынылады. Бұл шөл зона болғанымен жартастардағы жарықтарда су болуы мүмкін."}],questions:[{id:"1",competency:"explain",q:{type:"open",text:"Шарын шатқалының жер бедері қалай қалыптасты?",model:"Шарын шатқалының жер бедері экзогендік (сыртқы) күштердің әсерінен қалыптасты: тау жыныстарындағы ұзына бойы созылған аңғарды өзен салды, ал жартастардың көрікті пішіндері желдің әсерінен (желдік мүжілу) қалыптасты.",rubric:["Өзеннің жұмысын (аңғар) ЖӘНЕ желдің/мүжілудің әсерін атайды","Тек бір факторды атайды (өзен немесе жел)"]}},{id:"2",competency:"explain",q:{type:"single",text:"Ауа температурасының өзгеруі және жартас жарықтарындағы су жартастардың мүжіліп, бұзылуына қалай әсер етеді?",options:["Суық су жылы тастарды ерітеді","Су тастарды біріктіріп, қатырып тастайды","Мұз тастардың беттерін тегістейді","Қататын су жартастардың жарықтарында ұлғаяды"],answer:3,why:"Су қатқанда көлемі шамамен 9%-ға ұлғаяды да, жарықтарды кеңейтіп, жынысты бөлшектейді (аязды мүжілу)."}},{id:"3",competency:"data",q:{type:"single",text:"Неліктен Шарында тасқа айналған теңіз жануарларының қалдықтары сақталған? Осыдан миллион жылдай бұрын қандай оқиғалар болған?",options:["Ежелгі адамдар теңіз өнімдерін мұхиттардан осы аймаққа әкелген","Ертеде мұхиттар сұрапыл болып, теңіз тіршілік иелері алып толқындармен құрлыққа шығарылған","Ерте кезде бұл жерде теңіз болған, кейін ол шегініп, суы тартылған","Кейбір теңіз жануарлары теңізге шықпас бұрын құрлықта тіршілік еткен"],answer:2,why:"Теңіз жануарларының қалдықтары шөгінді жыныстардың ішінде — демек, бұл жыныстар ежелгі теңіз түбінде түзілген."}}]},{id:"solar",title:"Күн электр стансасы қайда тиімді?",grade:8,topic:"Климат",level:2,source:"НЗМ, 2020 · 2-тапсырма",stimuli:[{kind:"text",title:"Баламалы энергетика",body:"Баламалы энергетика туралы айтылғанда ең алдымен қалпына келетін энергия көздері — күн энергиясы мен жел энергиясы туралы айтылады. Күн электр стансасы күн батареясынан (тұрақты токтың генераторы), зарядты бақылайтын қондырғысы бар аккумулятордан және тұрақты токты ауыспалы токқа айналдыратын инвертордан тұрады. Күн батареялары күн энергиясын электр энергиясына айналдыратын күн элементтерінің жинақтарынан тұрады."},{kind:"climate",title:"№1 климатограмма",months:i=["Қаң","Ақп","Нау","Сәу","Мам","Мау","Шіл","Там","Қыр","Қаз","Қар","Жел"],temp:[14,16,20,25,29,32,33,33,30,25,19,15],precip:[5,4,6,3,2,0,0,1,1,3,5,6]},{kind:"climate",title:"№2 климатограмма",months:i,temp:[26,26,27,27,27,26,26,26,27,27,27,26],precip:[260,240,300,330,280,180,160,150,190,250,280,270]}],questions:[{id:"1",competency:"data",q:{type:"single",text:"Қай климатограмма күн батареяларын салу үшін едәуір қолайлы жерге сәйкес келеді?",options:["№1 климатограмма","№2 климатограмма","Екеуі бірдей қолайлы","Ешқайсысы қолайлы емес"],answer:0,why:"Күн батареясына жыл бойы ашық күндер көп болуы керек. №1 жерде жыл бойы жылы әрі жауын-шашын өте аз (тропиктік шөл) — бұлт аз. №2 жерде жауын көп — бұлтты күндер көп."}},{id:"2",competency:"inquiry",q:{type:"open",text:"Күн энергиясын алуды қазба отын (көмір не мұнай) қолданатын электр энергиясын өндірумен салыстырып, бір артықшылығы мен бір кемшілігін сипатта.",model:"Артықшылығы: энергия көзі сарқылмайды, қоршаған ортаны ластамайды, отынға шығын жоқ.\nКемшілігі: ауа райы мен тәулік уақытына тәуелді (түнде, бұлтта өндірмейді); жоғары ендіктерде тиімсіз; қондырғысы қымбат; үлкен аудан қажет.",rubric:["Бір дұрыс артықшылық ЖӘНЕ бір дұрыс кемшілік","Тек артықшылық немесе тек кемшілік"]}}]},{id:"climate-type",title:"Климатограмманы оқы",grade:8,topic:"Климат",level:3,source:"НЗМ, 2020 · 5-тапсырма",stimuli:[{kind:"climate",title:"Белгісіз станса",months:i,temp:[-38,-34,-22,-6,6,15,19,15,6,-8,-26,-36],precip:[8,7,6,8,15,35,48,44,26,14,10,8]}],questions:[{id:"1",competency:"data",q:{type:"single",text:"Станса қай климаттық белдеуде орналасқан?",options:["Тропиктік","Субтропиктік","Қоңыржай","Экваторлық"],answer:2,why:"Қыста температура 0 °С-тан төмен, жазда +10 °С-тан жоғары — қоңыржай белдеудің белгісі."}},{id:"2",competency:"data",q:{type:"single",text:"Станса қай жарты шарда орналасқан?",options:["Солтүстік жарты шарда","Оңтүстік жарты шарда","Экваторда","Анықтау мүмкін емес"],answer:0,why:"Ең суық ай — қаңтар, ең жылы ай — шілде. Демек қыс қаңтарға сәйкес келеді — солтүстік жарты шар."}},{id:"3",competency:"data",q:{type:"number",text:"Ауа температурасының жылдық амплитудасын есепте (ең жылы мен ең суық айдың айырмасы).",answer:57,tolerance:0,unit:"°С",why:"Шілде +19 °С, қаңтар −38 °С: 19 − (−38) = 57 °С."}},{id:"4",competency:"explain",q:{type:"open",text:"Климат типін анықта және климатограмма деректеріне сүйеніп, жауабыңды түсіндір.",model:"Шұғыл континентті климат: температураның жылдық амплитудасы өте үлкен (57 °С), жылдық жауын-шашын мөлшері аз (≈230 мм, 400 мм-ден төмен) және ол негізінен жаз айларында түседі.",rubric:["«Шұғыл континентті» + амплитуда ЖӘНЕ жауын-шашынның аздығы","Тек «континентті» немесе дәлелсіз жауап"]}}]},{id:"gis",title:"Геоақпараттық жүйелер (ГАЖ)",grade:9,topic:"Геоақпараттық технологиялар",level:1,source:"НЗМ, 2020 · 3-тапсырма",stimuli:[{kind:"text",title:"ГАЖ дегеніміз не?",body:"Географиялық ақпараттық жүйе (ГАЖ) — кеңістіктік ақпараттарды жинауға, өңдеуге, модельдеуге және талдауға, оларды есептеу кезінде қолдануға және көрсетуге, шешім шығаруға және қабылдауға арналған көпфункциялы ақпараттық жүйе. ГАЖ-дың негізгі міндеті — Жер, жеке аумақтар, жергілікті жерлер туралы білім қалыптастыру, сондай-ақ қажетті кеңістіктік деректерді қолданушыларға уақытылы жеткізу."}],questions:[{id:"1",competency:"explain",q:{type:"open",text:"ГАЖ технологияларын экологияда қалай қолдануға болады? Кемінде екі мысал келтір.",model:"Флора мен фауна деградациясының ауқымын анықтау; қоршаған ортаның ластану ауқымын анықтау; кадастрлар құрастыру; қорықтар мен қорықшаларды басқару; қоршаған орта мониторингін жүргізу.",rubric:["Екі немесе одан көп дұрыс мысал","Бір дұрыс мысал"]}},{id:"2",competency:"explain",q:{type:"single",text:"Төмендегі қосымшалардың қайсысы ГАЖ технологиясына жатпайды?",options:["2GIS","Google Maps","Яндекс Такси","Калькулятор"],answer:3,why:"2GIS, Google Maps, такси қосымшалары кеңістіктік (карталық) деректермен жұмыс істейді. Калькулятор — жоқ."}}]},{id:"sport",title:"Мектептің спорт алаңы",grade:7,topic:"План және карта",level:1,source:"НЗМ, 2020 · 4-тапсырма",stimuli:[{kind:"svg",title:"Жергілікті жердің планы",svg:'<svg viewBox="0 0 420 300" xmlns="http://www.w3.org/2000/svg" font-family="Inter,system-ui,sans-serif">\n<rect width="420" height="300" fill="#f7f3e3"/>\n<g fill="none" stroke="#b7791f" stroke-width="1.4">\n<path d="M10 60 C90 30 170 50 240 40 S380 60 410 30"/><path d="M10 90 C100 60 170 80 250 70 S380 90 410 62"/>\n<path d="M300 300 C310 250 360 230 410 225"/><path d="M260 300 C280 240 350 205 410 195"/></g>\n<g stroke="#2b6cb0" stroke-width="1.6"><path d="M40 170h70M46 180h58M40 190h70M50 200h50M44 210h62"/></g>\n<path d="M300 120 l18 70 l12 -40 l14 60" fill="none" stroke="#9b2c2c" stroke-width="2.4"/>\n<path d="M296 128 l6 -6 M312 160 l8 -4 M330 150 l8 4 M340 196 l8 -2" stroke="#9b2c2c" stroke-width="1.6"/>\n<path d="M0 255 C120 245 220 270 300 262" fill="none" stroke="#2b6cb0" stroke-width="3"/>\n<rect x="170" y="200" width="22" height="16" fill="#4a5568"/><text x="164" y="232" font-size="11" fill="#2d3748">Мектеп</text>\n<g font-size="22" font-weight="800" fill="#c53030"><text x="62" y="160">1</text><text x="190" y="140">2</text><text x="340" y="115">3</text></g>\n<text x="12" y="290" font-size="10" fill="#4a5568">Горизонтальдар 2,5 м арқылы · Масштаб 1:10 000</text>\n<g font-size="10" fill="#2d3748"><text x="250" y="288">— — батпақ   /\\/ жыра</text></g>\n</svg>',caption:"1, 2, 3 — спорт алаңына ұсынылған үлескілер"}],questions:[{id:"1",competency:"data",q:{type:"single",text:"1, 2 және 3 сандарымен берілген үлескілердің қайсысы мектептің спорт алаңын салуға ыңғайлы?",options:["№1 үлескі","№2 үлескі","№3 үлескі","Үшеуі де бірдей"],answer:1,why:"№2 үлескі ашық әрі тегіс, мектептің қасында. №1 жерде — батпақ, №3 жерде — жыра."}},{id:"2",competency:"data",q:{type:"number",text:"Планның масштабы 1:10 000. Мектептен №2 үлескіге дейін планда 1,5 см. Жердегі қашықтық неше метр?",answer:150,tolerance:0,unit:"м",why:"1:10 000 → 1 см-де 100 м. 1,5 × 100 = 150 м."}}]},{id:"jobs",title:"Ербол жұмыс іздейді",grade:9,topic:"Еңбек ресурстары",level:3,source:"НЗМ, 2020 · 6-тапсырма",stimuli:[{kind:"table",title:"Қазақстан: экономикалық белсенді халық, ІІ тоқсан (ҚР ҰЭМ Статистика комитеті)",head:["Жыл","Экономикалық белсенді халық, млн","Жұмыссыздар, мың адам"],rows:[[2015,9,448.5],[2016,8.9,447.4],[2017,9,439.3],[2018,9.1,441.4],[2019,9.2,441.8]]},{kind:"table",title:"Басқа елдер, 2018 ж.",head:["Ел","Жұмыссыздық деңгейі, %","Жұмыссыздар, млн адам"],rows:[["Қытай",4.7,37.6],["Украина",9.2,1.9],["Кувейт",1.1,.1]]}],questions:[{id:"1",competency:"data",q:{type:"number",text:"2019 жылғы деректер бойынша Қазақстандағы жұмыссыздық деңгейін есепте (бір ондық белгіге дейін).",answer:4.8,tolerance:.05,unit:"%",why:"441,8 мың / 9,2 млн × 100% = 4,8%."}},{id:"2",competency:"data",q:{type:"single",text:"Жұмыссыздық деңгейі «қалыпты» (4–6%), «төмен» (2–4%-дан аз) және «жоғары» (6%-дан көп) болады. Қай елде жұмыссыздық деңгейі жоғары?",options:["Қазақстан","Қытай","Украина","Кувейт"],answer:2,why:"Украинада 9,2% — 6%-дан жоғары. Қазақстан мен Қытайда қалыпты, Кувейтте өте төмен."}},{id:"3",competency:"explain",q:{type:"open",text:"Жұмыссыздықтың жоғары деңгейімен байланысты қандай қауіп-қатерлер бар?",model:"Қылмыстың өсуі; халықтың сатып алу қабілетінің төмендеуі; елдегі экономикалық жағдайдың нашарлауы; көші-қонның (еңбек миграциясының) артуы.",rubric:["Екі немесе одан көп қауіп-қатер","Бір қауіп-қатер"]}}]},{id:"schengen",title:"Шенген визасымен саяхат",grade:9,topic:"Халықаралық ұйымдар",level:2,source:"НЗМ, 2020 · 7-тапсырма",stimuli:[{kind:"text",title:"Шенген келісімі",body:"Шенген келісімі — Еуропалық Одақтың бірқатар елдерінің шекарасындағы төлқұжаттық-визалық бақылауды жеңілдету туралы келісім. Шенген визасы оның иесіне Шенген аймағындағы кез келген бір елден екінші елге еркін баруға мүмкіндік береді. Еуроодаққа мүше елдердің көпшілігінен басқа бұл аймаққа Исландия, Лихтенштейн, Норвегия және Швейцария кіреді. Ирландия Шенген аймағына кірмейді."}],questions:[{id:"1",competency:"data",q:{type:"yesno",text:"Қазақстандық турист Шенген визасымен мына елдерге бара ала ма?",rows:[["Нидерланды",!0],["Германия",!0],["Франция",!0],["Ирландия",!1],["Швейцария",!0]],why:"Ирландия Шенген аймағына кірмейді; Швейцария ЕО-ға мүше болмаса да, Шенген аймағында."}},{id:"2",competency:"explain",q:{type:"open",text:"Шенген визасы бар адамның қандай құқықтары бар?",model:"Шенген визасы иесіне Шенген аймағындағы бір елден екінші елге шекаралық бақылаусыз еркін баруға, сол елдерде виза мерзімі ішінде болуға мүмкіндік береді.",rubric:["Аймақ ішінде еркін жүріп-тұру (шекаралық бақылаусыз) деп түсіндіреді","Тек «Еуропаға баруға болады» дейді"]}}]},{id:"storm",title:"Дауыл келе жатыр",grade:9,topic:"Атмосфералық қауіпті құбылыстар",level:1,source:"НЗМ, 2020 · 8-тапсырма",stimuli:[{kind:"text",title:"Хабарландыру",body:"ТЖ департаменті хабарлайды: алдағы тәулікте облыс аумағында қатты жел күтіледі, екпіні секундына 25–30 метрге дейін жетеді, жергілікті жерлерде дауыл болады. Тұрғындардан сақтық шараларын сақтау сұралады.\n\nҚазақстан аумағында қатты желдер мен дауылдар жыл бойы байқалады: әсіресе Жоңғар қақпасында, Маңғыстауда, Арқада және Каспий маңында."}],questions:[{id:"1",competency:"inquiry",q:{type:"open",text:"Қатты дауылдың келе жатқаны туралы хабар берілді. Дауыл кезінде және оған дейін не істеу керек?",model:"Жел соққан жақтағы терезелерді, есіктерді, шатыр есіктерін жабу; балкон мен аулада жел ұшырып әкетуі мүмкін заттарды жинау; үйден шықпау, шықса — ағаштардан, электр сымдарынан, жарнама тақталарынан алыс болу; шам, су, азық, дәрі қорын дайындау; ТЖ хабарламаларын тыңдау.",rubric:["Үйдегі дайындық ЖӘНЕ сыртта қауіпсіздік шарасы","Тек бір шара"]}},{id:"2",competency:"explain",q:{type:"single",text:"Жоңғар қақпасында жиі соғатын күшті жел қалай аталады?",options:["Бриз","Ебі","Муссон","Пассат"],answer:1,why:"Ебі — Жоңғар қақпасынан соғатын күшті, суық жел."}}]},{id:"cyclone",title:"Циклон мен антициклон",grade:7,topic:"Атмосфера",level:2,source:"«Географическая PISA», Теміртау, 2016 · «Циклоны и антициклоны»",stimuli:[{kind:"text",title:"Ауа райы болжамы",body:"Ауа райы болжамында атмосфералық қысым, температура, ылғалдылық, жауын-шашын, жел мен бұлттылықпен қатар циклондар мен антициклондардың қозғалысы туралы да хабарланады.\n\nЦиклон — орталығында қысымы ең төмен аймақ. Ол жылы ауа суық ауаға кіргенде пайда болады; ауа жоғары көтеріледі, солтүстік жарты шарда сағат тіліне қарсы айналады. Жазда аптапты, қыста аязды жұмсартады.\n\nАнтициклон — орталығында қысымы ең жоғары аймақ. Ол суық ауа жылы ауаға кіргенде пайда болады; ауа төмен түседі, солтүстік жарты шарда сағат тілімен айналады. Жазда аптапты, қыста аязды күшейтеді."}],questions:[{id:"1",competency:"explain",q:{type:"yesno",text:"Мына пікірлермен келісесің бе?",rows:[["Циклонда ауа орталықтан шетке қарай қозғалады",!1],["Антициклон кезіндегі ашық күн жоғары көтерілген ауа ағынымен түсіндіріледі",!1],["Циклон кезінде бұлтты, жауын-шашынды ауа райы орнайды",!0]],why:"Циклонда ауа шеттен орталыққа келіп, жоғары көтеріледі; антициклонда ауа төмен түседі, сондықтан бұлт түзілмейді."}},{id:"2",competency:"explain",q:{type:"open",text:"Неліктен циклон кезінде бұлтты, жауын-шашынды, ал антициклон кезінде ашық әрі құрғақ ауа райы орнайды?",model:"Циклонда ауа жер бетінен су буымен бірге жоғары көтеріледі; биікте суып, су буы конденсацияланады — бұлт түзіліп, жауын жауады. Антициклонда ауа жоғарыдан төмен түседі, түскенде жылынып, қанығу күйінен алыстайды — бұлт түзілмейді, ауа райы ашық және құрғақ.",rubric:["Көтерілу→суу→конденсация ЖӘНЕ төмен түсу→жылыну деп екеуін де түсіндіреді","Тек біреуін түсіндіреді"]}},{id:"3",competency:"inquiry",q:{type:"single",text:"Ластанған өнеркәсіп қаласында жер бетіне жақын қабаттағы ластаушы заттардың шоғырлануы қай ауа райында жоғары болады?",options:["Антициклондық — тынық, ауа төмен түседі","Циклондық — жел мен жауын бар"],answer:0,why:"Антициклонда жел әлсіз, ауа төмен түседі — ластанған ауа қала үстінде жиналып қалады (смог). Циклонда жел мен жауын ауаны тазартады."}}]},{id:"balkhash",title:"Балқаш көлі",grade:8,topic:"Ішкі сулар",level:2,source:"«Географическая PISA», Теміртау, 2016 · «Озеро Балхаш»",stimuli:[{kind:"text",title:"Туристік агенттіктің хабарламасы",body:"Балқаш — ағынсыз, жартылай тұщы көл, әлемдегі көлдердің ішінде көлемі жағынан он үшінші. Көл теңіз деңгейінен 340 м биіктікте жатыр, ауданы 18 000 км²-ден асады, ұзындығы 600 км-ден артық. Орташа тереңдігі небәрі 5 м, ең терең жері — 26 м.\n\nБалқаштың ерекшелігі — оның бір жартысы тұзды, ал екінші жартысы іс жүзінде тұщы. Оларды ені 4 км ғана болатын тар Ұзынарал бұғазы бөліп тұр, сондықтан су араласпайды. Көлге көп өзен құяды, ең ірісі — Тянь-Шаньнан бастау алатын, ұзындығы 1500 км-ге жуық Іле өзені. Қалған өзендер шағын — Лепсі, Қаратал, Ақсу.\n\nКөлде 20-дан астам балық түрі бар, оның 6-ы ежелден мекендейтін жергілікті түрлер (Іле маринкасы, балқаш маринкасы, балқаш алабұғасы, теңбіл талма балық, балқаш гольяны т.б.)."}],questions:[{id:"1",competency:"data",q:{type:"yesno",text:"Мына пікірлермен келісесің бе?",rows:[["Балқаш көлі Қазақстан мен Қытай аумағында орналасқан",!1],["Балқаш — таулы көл",!1],["Балқаш — ағынсыз көл",!0]],why:"Балқаш толығымен Қазақстан аумағында, 340 м биіктіктегі жазықта жатыр; көлден ағып шығатын өзен жоқ."}},{id:"2",competency:"explain",q:{type:"single",text:"Балқаштың қай бөлігі тұщы?",options:["Батыс бөлігі","Шығыс бөлігі","Екі бөлігі де тұщы","Екі бөлігі де тұзды"],answer:0,why:"Батыс бөлігіне көлдің тұщы суының ~75%-ын беретін Іле өзені құяды. Шығыс бөлігіне құятын Лепсі, Қаратал, Ақсу шағын өзендер."}},{id:"3",competency:"inquiry",q:{type:"single",text:"Балықшының торында қайсысы «артық» — Балқашта бола алмайды?",options:["Балқаш алабұғасы","Сазан","Балқаш дельфині","Табан балық"],answer:2,why:"Дельфин — теңіз жануары, тұщы көлде мекендемейді."}},{id:"4",competency:"data",q:{type:"number",text:"Балқаштың ауданы 18 000 км², орташа тереңдігі 5 м. Көлдегі судың көлемі шамамен неше км³?",answer:90,tolerance:0,unit:"км³",why:"5 м = 0,005 км. 18 000 × 0,005 = 90 км³."}}]}])}}});